// drawer, the chronicle codex frame, the inspector, the social graph, badges.
// Values may carry {x} placeholders filled by t(key, params).
// This file holds DATA only; all logic lives in i18n.js. English is the
// fallback for any missing key, so a partial translation never breaks the UI.
// ============================================================================

